    @Test func allBitsSet() {
        let mismatches = Mismatches("portAllBitsSetI16InVectorCode")
        let aInputs =
            Inputs.vectors(H.self, seed: 0x8AE9_98ED_D27A_DF2E)
            + (0..<H.laneCount).flatMap { lane in
                [Lane.zero, ~Lane.zero].map { uniform in
                    H(H.SIMDType((0..<H.laneCount).map { $0 == lane ? uniform ^ 1 : uniform }))
                }
            }
        for a in aInputs {
            mismatches.check(
                { () -> Bool in
                    var a = a
                    return unsafe portAllBitsSetI16InVectorCode(&a)
                }(),
                { () -> Bool in
                    var a = a
                    return unsafe highwayAllBitsSetI16InVectorCode(&a)
                }(),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
